int main(){bool css_geometry_pass=true;Fixture f("<html><body><div id='p'></div></body></html>");f.sheet("html{overflow:auto}body{background:#123456}#p{height:1000.5px}");f.resolve();aether_layout_result_t layout{};ok(aether_layout_layout(f.engine,f.doc,f.map,1280,720,nullptr,nullptr,&layout),"layout");auto root=layout->root;printf("BODY border x=%g y=%g width=%g height=%g bottom=%g\n",root->border_box.x,root->border_box.y,root->border_box.width,root->border_box.height,root->border_box.y+root->border_box.height);need(root->border_box.x==8&&root->border_box.width==1264,"body horizontal margin8 retained");DocumentTextBudget budget;auto auth=DocumentTextTestAccess::viewport(f.doc,layout,f.map,{},budget);auto d=auth.diagnostics();printf("Range y=%.17g extent=%.17g\n",d.range_y,d.extent_height);need(d.range_y==296.5&&d.extent_height==1016.5,"fractional extent includes body margins");auto floor=uint32_t(std::floor(d.range_y));auto end=DocumentTextTestAccess::viewport(f.doc,layout,f.map,{0,floor},budget);need(end.diagnostics().offset.y==floor,"integer offsetfloor accepted");bool rejected=false;try{auto bad=DocumentTextTestAccess::viewport(f.doc,layout,f.map,{0,floor+1},budget);}catch(...){rejected=true;}need(rejected,"no clamp beyond fractionalrange");need(auth.accepts(layout,f.map),"current snapshot");auto old=root->content_box.x;root->content_box.x+=.25;need(!auth.accepts(layout,f.map),"geometry stale rejects");root->content_box.x=old;need(auth.accepts(layout,f.map),"exact restored snapshot");std::thread t([&]{need(!auth.accepts(layout,f.map),"wrongthread");});t.join();Fixture other("<html><body></body></html>");need(!auth.accepts(layout,other.map),"foreign map");aether_display_list_builder_t builder{};ok(aether_display_list_builder_create(nullptr,nullptr,&builder),"builder");std::unique_ptr<aether::rendering::NativePaintList> list;ok(aether::rendering::build_native_document_capture(builder,layout,f.map,end,list),"document scroll builder");need(bool(list),"actual list");aether_display_list_builder_destroy(builder);
aether_layout_result_destroy(layout);
{Fixture single("<html><body><div></div></body></html>");single.sheet("html{overflow:auto}");single.resolve();aether_layout_result_t sole{};ok(aether_layout_layout(single.engine,single.doc,single.map,1280,720,nullptr,nullptr,&sole),"sole layout");bool released=false;printf("SOLE factory begin\n");auto retained=DocumentTextTestAccess::viewport(single.doc,sole,single.map,{},budget,[&]{if(!released){aether_layout_result_destroy(sole);released=true;}});need(released&&retained.accepts(sole,single.map),"factory pin protects sole callerref release");}
printf("SOLE factory completed\n");{Fixture collapsed("<html><body><div id='p'></div></body></html>");collapsed.sheet("html{overflow:auto}#p{height:1000.5px;margin-top:20px;margin-bottom:30px}");collapsed.resolve();aether_layout_result_t l{};ok(aether_layout_layout(collapsed.engine,collapsed.doc,collapsed.map,1280,720,nullptr,nullptr,&l),"collapsed layout");printf("COLLAPSED pre factory root y=%g h=%g marginY=%g marginH=%g before=%g after=%g childmarginY=%g\n",l->root->border_box.y,l->root->border_box.height,l->root->margin_box.y,l->root->margin_box.height,l->root->collapsed_margin_before,l->root->collapsed_margin_after,l->root->children.front()->margin_box.y);auto a=DocumentTextTestAccess::viewport(collapsed.doc,l,collapsed.map,{},budget);printf("COLLAPSED y=%g h=%g before=%g after=%g extent=%g\n",l->root->border_box.y,l->root->border_box.height,l->root->collapsed_margin_before,l->root->collapsed_margin_after,a.diagnostics().extent_height);need(a.diagnostics().extent_height==double(l->root->border_box.y)+l->root->border_box.height+30,"authority ledger trailing margin once");css_geometry_pass=l->root->border_box.y==20&&a.diagnostics().extent_height==1050.5;printf("CSS_GEOMETRY expected borderY20 extent1050.5 observedY%g extent%g status=%s\n",l->root->border_box.y,a.diagnostics().extent_height,css_geometry_pass?"PASS":"KNOWN_FAIL");auto flags=l->root->scroll_completion_flags;printf("AUTHENTIC root completion flags=%u\n",unsigned(flags));l->root->scroll_completion_flags^=1;need(!a.accepts(l,collapsed.map),"completion flag tamper rejects stale");l->root->scroll_completion_flags=flags;need(a.accepts(l,collapsed.map),"restored complete snapshot");l->root->scroll_completion_flags|=8;bool table_rejected=false;try{auto bad=DocumentTextTestAccess::viewport(collapsed.doc,l,collapsed.map,{},budget);}catch(...){table_rejected=true;}need(table_rejected,"table-cell flag rejected");l->root->scroll_completion_flags=flags;aether_layout_result_destroy(l);}printf("Viewport authority checks=%u; CSS geometry=%s\n",checks,css_geometry_pass?"PASS":"KNOWN_FAIL");return css_geometry_pass?0:1;}
